· engaging in other activities that are necessary, suitable or convenient to accomplish the foregoing or are incidental to or connected with the activities listed above.", "score": 0.1723, "deals": [{"deal_name": "Honda Auto Receivables 2024-4 Owner Trust", "series": "", "accession": "0001104659-24-107060", "filing_date": "2024-10-08", "asset_class": "Auto loan", "page": "43", "doc_url": "https://www.sec.gov/Archives/edgar/data/890975/000110465924107060/tm2424075d3_424h.htm", "text_file": "data/text/AMERICAN_HONDA_RECEIVABLES_LLC_2024-10-08_424H.txt", "char_start": 133393, "char_end": 135003}], "supporting_quote_matched": false, "matched_expected_deal_ids": []}]

